const listProductsFiltered = `-- name: ListProductsFiltered :many
SELECT p.id, p.shop_id, p.category_id, p.name, p.description, p.images, p.status,
       p.rejection_reason, p.min_price_vnd, p.max_price_vnd, p.deleted_at, p.created_at, p.updated_at
FROM products p
WHERE p.deleted_at IS NULL
  AND ($1::text = '' OR p.category_id = $1::text OR p.category_id IN (SELECT c.id FROM categories c WHERE c.parent_id = $1::text))
  AND ($2::text = '' OR p.name ILIKE '%' || $2::text || '%' OR p.description ILIKE '%' || $2::text || '%')
  AND ($3::text = '' OR p.shop_id = $3::text)
  AND (NOT $4::bool OR p.status IN ('APPROVED', 'OUT_OF_STOCK'))
  AND ($5::text = '' OR p.status = $5::text)
  AND (
    ($6::bigint <= 0 AND $7::bigint <= 0)
    OR EXISTS (
      SELECT 1 FROM skus s
      WHERE s.product_id = p.id
        AND s.status <> 'INACTIVE'
        AND ($6::bigint <= 0 OR s.price_vnd >= $6::bigint)
        AND ($7::bigint <= 0 OR s.price_vnd <= $7::bigint)
    )
  )
ORDER BY
  CASE WHEN $8::text = 'price_asc' THEN p.min_price_vnd END ASC,
  CASE WHEN $8::text = 'price_desc' THEN p.max_price_vnd END DESC,
  CASE WHEN $8::text = 'name_asc' THEN p.name END ASC,
  CASE WHEN $8::text = 'oldest' THEN p.created_at END ASC,
  p.created_at DESC,
  p.id DESC
LIMIT $10::int
OFFSET $9::int
`

