const updateSKUStockOptimistic = `-- name: UpdateSKUStockOptimistic :one

UPDATE skus
SET stock = $1,
    status = CASE
        WHEN status = 'INACTIVE' THEN 'INACTIVE'
        WHEN $1 = 0 THEN 'OUT_OF_STOCK'
        ELSE 'ACTIVE'
    END,
    version = version + 1,
    updated_at = NOW()
WHERE id = $2
  AND version = $3
  AND $1 >= (reserved_stock + flash_sale_reserved_stock)
RETURNING id, product_id, sku_code, name, attributes, price_vnd, stock,
          reserved_stock, version, weight_grams, image_url, status, created_at, updated_at, flash_sale_reserved_stock
`

type UpdateSKUStockOptimisticParams struct {
	Stock   int32
	ID      string
	Version int64
}

// Stock optimistic locking
func (q *Queries) UpdateSKUStockOptimistic(ctx context.Context, arg UpdateSKUStockOptimisticParams) (Sku, error) {
	row := q.db.QueryRow(ctx, updateSKUStockOptimistic, arg.Stock, arg.ID, arg.Version)
	var i Sku
	err := row.Scan(
		&i.ID,
		&i.ProductID,
		&i.SkuCode,
		&i.Name,
		&i.Attributes,
		&i.PriceVnd,
		&i.Stock,
		&i.ReservedStock,
		&i.Version,
		&i.WeightGrams,
		&i.ImageURL,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.FlashSaleReservedStock,
	)
	return i, err
}
